"use client";

import React, { InputHTMLAttributes } from "react";

import { useFieldDescription } from "../hooks/useFieldDescription";
import { useStableId } from "../hooks/useStableId";
import styles from "./CyberpunkSlider.module.css";

export interface CyberpunkSliderProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "helperText"> {
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  showValue?: boolean;
  helperText?: string;
  error?: string;
}

/** Fill percentage for the track; 0 when max===min or non-finite. Clamped to [0, 100]. */
export function sliderPercentage(
  value: number | string,
  min: number,
  max: number,
): number {
  const range = max - min;
  const percentage = range === 0 ? 0 : ((Number(value) - min) / range) * 100;
  return Number.isFinite(percentage)
    ? Math.min(100, Math.max(0, percentage))
    : 0;
}

export function CyberpunkSlider({
  label,
  className = "",
  id,
  min = 0,
  max = 100,
  step = 1,
  showValue = true,
  value = 0,
  helperText,
  error,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: CyberpunkSliderProps) {
  const inputId = useStableId("slider", id);
  const percentage = sliderPercentage(value as number | string, min, max);
  const { errorId, hasError, helperId, describedBy } = useFieldDescription({
    prefix: "slider",
    helperText,
    error,
    describedBy: ariaDescribedBy,
  });

  return (
    <div className={`${styles.wrapper} ${hasError ? styles.hasError : ""} ${className}`.trim()}>
      {label ? (
        <label htmlFor={inputId} className={styles.label}>
          {label}
        </label>
      ) : null}
      <div className={styles.sliderContainer}>
        <div
          className={styles.track}
          style={
            {
              ["--slider-percentage" as string]: percentage,
            } as React.CSSProperties
          }
        >
          <div className={styles.trackBase} aria-hidden="true" />
          <div className={styles.fill} aria-hidden="true" />
          <input
            id={inputId}
            type="range"
            min={min}
            max={max}
            step={step}
            value={value}
            className={styles.slider}
            {...props}
            aria-invalid={ariaInvalid ?? (hasError ? true : undefined)}
            aria-describedby={describedBy}
          />
        </div>
        {showValue ? <span className={styles.value}>{value}</span> : null}
      </div>
      {helperText ? (
        <div id={helperId} className={styles.helperText}>
          {helperText}
        </div>
      ) : null}
      {hasError ? (
        <div id={errorId} className={styles.errorText} role="alert">
          {error}
        </div>
      ) : null}
    </div>
  );
}

.wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  font-size: 0.875rem;
  color: var(--text-primary);
  font-weight: 500;
}

.sliderContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.track {
  --thumb-size: 28px;
  position: relative;
  flex: 1;
  height: 32px;
  display: flex;
  align-items: center;
}

.trackBase {
  position: absolute;
  inset-inline: 0;
  height: var(--thumb-size);
  border: 2px solid var(--border);
  border-radius: calc(var(--thumb-size) / 2);
  background: var(--bg-primary);
  pointer-events: none;
  transition: border-color var(--transition-fast);
}

.fill {
  position: absolute;
  left: 0;
  height: var(--thumb-size);
  border-radius: calc(var(--thumb-size) / 2);
  background: var(--success);
  /* Meet the thumb center at every value — no gap, no overshoot past the knob. */
  width: calc(
    (var(--thumb-size) / 2) +
      (100% - var(--thumb-size)) * var(--slider-percentage, 0) / 100
  );
  pointer-events: none;
  transition: width var(--transition-fast);
}

.slider {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 32px;
  margin: 0;
  padding: 0;
  appearance: none;
  background: transparent;
  outline: none;
  cursor: pointer;
}

.slider::-webkit-slider-runnable-track {
  height: var(--thumb-size);
  background: transparent;
  border: none;
}

.slider::-webkit-slider-thumb {
  appearance: none;
  width: var(--thumb-size);
  height: var(--thumb-size);
  margin-top: 0;
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  border: 2px solid color-mix(in srgb, var(--success) 35%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
  transition: box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.slider::-moz-range-track {
  height: var(--thumb-size);
  background: transparent;
  border: none;
}

.slider::-moz-range-thumb {
  width: var(--thumb-size);
  height: var(--thumb-size);
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  border: 2px solid color-mix(in srgb, var(--success) 35%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
  transition: box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.track:hover .trackBase {
  border-color: var(--success);
}

.slider:focus-visible {
  box-shadow: none;
}

.slider:focus-visible::-webkit-slider-thumb {
  box-shadow:
    0 0 0 2px var(--bg-primary),
    0 0 0 4px color-mix(in srgb, var(--success) 55%, transparent),
    0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
}

.slider:focus-visible::-moz-range-thumb {
  box-shadow:
    0 0 0 2px var(--bg-primary),
    0 0 0 4px color-mix(in srgb, var(--success) 55%, transparent),
    0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
}

.slider:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.track:has(.slider:disabled) .fill,
.track:has(.slider:disabled) .trackBase {
  opacity: 0.5;
}

.value {
  font-size: 0.875rem;
  color: var(--success);
  font-weight: 600;
  min-width: 3rem;
  text-align: center;
  font-family: var(--font-mono);
}

.helperText {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

.hasError .label {
  color: var(--danger, #ff5c5c);
}

.hasError .trackBase {
  border-color: var(--danger, #ff5c5c);
}

.errorText {
  margin-top: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--danger, #ff5c5c);
  line-height: 1.3;
}

@media (prefers-reduced-motion: reduce) {
  .fill,
  .trackBase,
  .slider::-webkit-slider-thumb,
  .slider::-moz-range-thumb {
    transition: none;
  }
}
